package omissiondetection

import (
	"fmt"
	"sort"
	"strings"

	"github.com/farlleyferreira/conjecture-ai/internal/cjtr"
	"github.com/farlleyferreira/conjecture-ai/internal/conformancecycle"
)

// TypeBOmission is one domain case - generated by property-based test
// generation from one hypothesis's own boundary data - that no
// hypothesis in the checked set actually addresses.
type TypeBOmission struct {
	// GeneratedFrom is the name of the hypothesis whose own worked
	// example and boundary values produced Input - the hypothesis that
	// found the gap, not necessarily (and, by construction, never) one
	// that addresses it.
	GeneratedFrom string
	Input         cjtr.Bindings
}

// CheckTypeB detects Type B omissions - "Type B - case forgotten
// within the domain": "The system SHALL detect a domain case that the
// specification does not address, using property-based testing
// combined with targeted attacks... WHEN property-based test
// generation finds an input within the domain that no rule addresses
// THEN the system flags it as a Type B omission."
//
// hypotheses is the set CheckTypeB checks for joint coverage - the
// caller's own choice of scope, since the specification names no
// concrete boundary for "the domain" or "a rule addresses" it. This
// package recommends passing one rule's own hypotheses (what
// cjtr.Hypotheses(rule.Body, concepts) already returns, the same
// grouping check.go already iterates by): a rule's hypotheses are
// meant to jointly partition the domain its own Given conditions
// range over, which is exactly the shape a coverage gap is
// meaningful against. Passing a wider or narrower set changes what
// "addressed" means, not what this function computes.
//
// Generation reuses [conformancecycle.DirectedSamplingInputs] -
// conformance-cycle's own existing "centenas de entradas do domínio,
// concentradas em fronteiras, partições" machinery, directed
// sampling's own rigor-level wording for exactly "property-based
// testing... concentrated on boundaries" - run once per hypothesis in
// hypotheses that declares a worked example (DirectedSamplingInputs'
// own precondition; a hypothesis with none is simply not a generator
// here, the same honest "nothing to invent" posture this package's
// own Type A already takes for a hypothesis with no exercised cases).
//
// A generated case counts as addressed when at least one hypothesis
// in hypotheses actually applies to it: a universal hypothesis always
// does (its own "always" clause has no given-condition branch to
// fail), and a non-universal one does when every one of its own Given
// statements both resolves and holds against the case (the "and"
// combination [cjtr.Hypothesis.Given]'s own doc comment already
// states). A Given statement that cannot even be resolved against a
// candidate - typically a concept this candidate's own generating
// hypothesis never gave a baseline value for, because it belongs to a
// sibling hypothesis's own worked example instead - is read as "does
// not hold," not as an error: this package cannot distinguish "this
// hypothesis's condition is false here" from "this hypothesis's own
// domain was never described for this input," and treating the
// latter as coverage would be a guess, not a grounded finding.
//
// Omissions are deduplicated by their own serialized bindings, so the
// same uncovered case generated from two different hypotheses' own
// boundary search is reported once.
func CheckTypeB(hypotheses []cjtr.Hypothesis, concepts map[string]cjtr.Concept, tables cjtr.Tables) ([]TypeBOmission, error) {
	seen := make(map[string]bool)
	var omissions []TypeBOmission

	for _, h := range hypotheses {
		if len(h.Examples) == 0 {
			continue
		}
		cases, err := conformancecycle.DirectedSamplingInputs(h, concepts)
		if err != nil {
			return nil, fmt.Errorf("omissiondetection: generating candidates from %q: %w", h.Name, err)
		}

		for _, candidate := range cases {
			if addressedByAny(hypotheses, concepts, tables, candidate) {
				continue
			}
			key := bindingsKey(candidate)
			if seen[key] {
				continue
			}
			seen[key] = true
			omissions = append(omissions, TypeBOmission{GeneratedFrom: h.Name, Input: candidate})
		}
	}
	return omissions, nil
}

// addressedByAny reports whether at least one hypothesis in
// hypotheses applies to bindings - see [CheckTypeB]'s own doc comment
// for what "applies" means for a universal versus a conditional
// hypothesis.
func addressedByAny(hypotheses []cjtr.Hypothesis, concepts map[string]cjtr.Concept, tables cjtr.Tables, bindings cjtr.Bindings) bool {
	for _, h := range hypotheses {
		if h.IsUniversal {
			return true
		}
		if givenHolds(h, concepts, tables, bindings) {
			return true
		}
	}
	return false
}

// givenHolds reports whether every one of h's own Given statements
// resolves and holds against bindings - false the moment any one does
// not, including one that cannot be resolved at all (see
// [CheckTypeB]'s own doc comment on why that is read as "does not
// hold" rather than propagated as an error).
func givenHolds(h cjtr.Hypothesis, concepts map[string]cjtr.Concept, tables cjtr.Tables, bindings cjtr.Bindings) bool {
	for _, stmt := range h.Given {
		ok, err := cjtr.Evaluate(stmt, concepts, tables, bindings)
		if err != nil || !ok {
			return false
		}
	}
	return true
}

// bindingsKey renders bindings as a deterministic string, regardless
// of map iteration order, for [CheckTypeB]'s own deduplication.
func bindingsKey(b cjtr.Bindings) string {
	keys := make([]string, 0, len(b))
	for k := range b {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		parts = append(parts, k+"="+b[k])
	}
	return strings.Join(parts, "\x00")
}
